class Solution { fun longestDiverseString(a:Int,b:Int,c:Int):String{val heap=java.util.PriorityQueue<IntArray>{x,y->if(x[0]!=y[0])y[0]-x[0] else x[1]-y[1]};if(a>0)heap.add(intArrayOf(a,'a'.code));if(b>0)heap.add(intArrayOf(b,'b'.code));if(c>0)heap.add(intArrayOf(c,'c'.code));val answer=StringBuilder();while(heap.isNotEmpty()){val first=heap.remove();val length=answer.length;if(length>=2&&answer[length-1].code==first[1]&&answer[length-2].code==first[1]){if(heap.isEmpty())break;val second=heap.remove();answer.append(second[1].toChar());second[0]--;if(second[0]>0)heap.add(second);heap.add(first)}else{answer.append(first[1].toChar());first[0]--;if(first[0]>0)heap.add(first)}};return answer.toString()} }
